-- 1. TABLA DE REGISTROS DE SOLICITUDES
CREATE TABLE IF NOT EXISTS public.solicitudes_licencia (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  rut TEXT NOT NULL,
  nombre_completo TEXT NOT NULL,
  empresa TEXT,
  faena TEXT,
  comuna TEXT,
  cargo_desempeno TEXT,
  motivo_solicitud TEXT,
  datos_formulario JSONB NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_solicitudes_licencia_rut ON public.solicitudes_licencia(rut);
CREATE INDEX IF NOT EXISTS idx_solicitudes_licencia_created_at ON public.solicitudes_licencia(created_at DESC);
ALTER TABLE public.solicitudes_licencia DISABLE ROW LEVEL SECURITY;

-- 2. TABLA DE CONFIGURACIÓN GLOBAL (Empresas, Faenas, HSEC, Mapeos)
CREATE TABLE IF NOT EXISTS public.licencia_configuracion (
  id TEXT PRIMARY KEY DEFAULT 'global',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  config JSONB NOT NULL
);

ALTER TABLE public.licencia_configuracion DISABLE ROW LEVEL SECURITY;

