-- 3. TABLA DE PLANTILLAS WORD (.docm / .docx)
CREATE TABLE IF NOT EXISTS public.licencia_plantillas (
  id TEXT PRIMARY KEY DEFAULT 'default',
  filename TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  archivo_base64 TEXT NOT NULL
);

ALTER TABLE public.licencia_plantillas DISABLE ROW LEVEL SECURITY;

